#!/usr/bin/env node
// Regenerate index.html from content.json. Zero dependencies.
//   node build/build-index.js
//
// Newlines are built with String.fromCharCode(10) rather than an escaped
// literal, because this file is itself generated by a shell heredoc and the
// escape keeps getting mangled in transit.
const fs = require('fs');
const path = require('path');

const NL = String.fromCharCode(10);
const ROOT = path.resolve(__dirname, '..');
const data = JSON.parse(fs.readFileSync(path.join(ROOT, 'content.json'), 'utf8'));
const site = data.site;

const ready = data.topics.filter(function (t) { return t.status === 'ready'; });
const planned = data.topics.filter(function (t) { return t.status !== 'ready'; });
const KIND_ORDER = ['essay', 'reference', 'cheatsheet'];

// Fields may carry HTML entities (e.g. &amp;), so they are emitted verbatim.
// They are authored here, not user input.
function esc(s) { return s == null ? '' : String(s); }

function extras(t) {
  if (!t.extras || !t.extras.length) return '';
  return t.extras.map(function (e) {
    return '<a href="' + esc(e.href) + '">' + esc(e.label) + '</a>';
  }).join(' &nbsp;&middot;&nbsp; ');
}

function card(t) {
  var style = ' style="--ca:' + esc(t.tagColor) + '"';
  var tags = '<div class="tags"><span class="tag" style="background:'
    + esc(t.tagColor) + '">' + esc(t.tag) + '</span>'
    + (t.status === 'ready' ? '' : '<span class="pill-soon">Coming soon</span>')
    + '</div>';
  if (t.status === 'ready') {
    var links = extras(t);
    return '<div class="c"' + style + '>' + tags
      + '<h2><a href="' + esc(t.html) + '">' + esc(t.title) + '</a></h2>'
      + '<p class="m">' + esc(t.blurb) + '</p>'
      + (links ? '<p class="links">' + links + '</p>' : '')
      + '</div>';
  }
  return '<div class="c soon"' + style + '>' + tags
    + '<h2>' + esc(t.title) + '</h2>'
    + '<p class="m">' + esc(t.blurb) + '</p></div>';
}

// ---- derived numbers for the hero, so they cannot drift from the data ----
var essayCount = ready.filter(function (t) { return t.kind === 'essay'; }).length;
var cardCount = ready.reduce(function (n, t) { return n + (t.cards || 0); }, 0);
var sheetCount = ready.filter(function (t) { return t.kind === 'cheatsheet'; }).length;
var pdfCount = ready.filter(function (t) {
  return (t.extras || []).some(function (e) { return e.label === 'PDF'; });
}).length;

var hero = site.hero || {};
var groups = site.groups || {};

var out = [];
out.push('<!DOCTYPE html>');
out.push('<html lang="en"><head><meta charset="utf-8">');
out.push('<meta name="viewport" content="width=device-width,initial-scale=1">');
out.push('<title>' + esc(site.title) + '</title>');
out.push('<link rel="stylesheet" href="assets/site.css">');
out.push('</head><body>');
out.push('<div class="w">');

out.push('  <header class="masthead">');
out.push('    <a class="mark" href="index.html"><span class="mark-glyph">G</span>'
  + '<span class="mark-name">' + esc(site.title) + '</span></a>');
out.push('    <div class="meta">' + esc(hero.eyebrow) + '</div>');
out.push('  </header>');

out.push('  <section class="hero">');
out.push('    <p class="eyebrow">Generative AI \u00b7 study notes</p>');
out.push('    <h1 class="display">' + esc(hero.title) + '</h1>');
out.push('    <p class="lede">' + esc(hero.lede) + '</p>');
out.push('    <div class="actions">');
out.push('      <a class="btn" href="' + esc(hero.primary.href) + '">'
  + esc(hero.primary.label) + '</a>');
out.push('      <a class="btn ghost" href="' + esc(hero.secondary.href) + '">'
  + esc(hero.secondary.label) + '</a>');
out.push('    </div>');
out.push('    <ul class="stats">');
out.push('      <li><b>' + essayCount + '</b>essays</li>');
out.push('      <li><b>' + cardCount + '</b>recall cards</li>');
out.push('      <li><b>' + sheetCount + '</b>cheat sheets</li>');
out.push('      <li><b>' + pdfCount + '</b>PDFs</li>');
out.push('    </ul>');
out.push('  </section>');

KIND_ORDER.forEach(function (kind) {
  var g = groups[kind];
  if (!g) return;
  var items = ready.filter(function (t) { return t.kind === kind; })
    .concat(planned.filter(function (t) { return t.kind === kind; }));
  if (!items.length) return;
  var id = kind === 'cheatsheet' ? 'cheatsheets' : kind === 'essay' ? 'essays' : 'reference';
  out.push('');
  out.push('  <section class="group" id="' + id + '">');
  out.push('    <h2 class="group-title">' + esc(g.title) + '</h2>');
  out.push('    <p class="group-sub">' + esc(g.sub) + '</p>');
  // essays and the reference sheet have longer blurbs: two wider columns
  out.push('    <div class="grid' + (kind === 'cheatsheet' ? '' : ' grid--wide') + '">');
  items.forEach(function (t) { out.push('      ' + card(t)); });
  out.push('    </div>');
  out.push('  </section>');
});

out.push('');
out.push('  <footer>' + esc(site.footer) + '</footer>');
out.push('</div>');
out.push('</body></html>');
out.push('');

fs.writeFileSync(path.join(ROOT, 'index.html'), out.join(NL));
console.log('built index.html  topics=' + data.topics.length
  + ' ready=' + ready.length + ' planned=' + planned.length
  + ' groups=' + KIND_ORDER.length);
